<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\CommissionService;require_role('TRAINER');$u=current_user();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{CommissionService::completeSession((int)$_POST['session_id'],(int)$u['TrainerID']);set_flash('success','Session completed and commission calculated.');redirect('trainer/commissions.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$sessions=db_all("SELECT s.SessionID,s.StartsAt,s.Status,c.ClassName,c.RatePerClass,ce.Amount Commission,ce.Status CommissionStatus FROM CLASS_SESSION s JOIN CLASS c ON c.ClassID=s.ClassID LEFT JOIN COMMISSION_ENTRY ce ON ce.SessionID=s.SessionID WHERE c.TrainerID=? ORDER BY s.StartsAt DESC",'i',[$u['TrainerID']]);$totals=db_one("SELECT COALESCE(SUM(CASE WHEN Status='EARNED' THEN Amount ELSE 0 END),0) Earned,COALESCE(SUM(CASE WHEN Status='PAID' THEN Amount ELSE 0 END),0) Paid FROM COMMISSION_ENTRY WHERE TrainerID=?",'i',[$u['TrainerID']]);$pageTitle='Commission';$pageSubtitle='Earnings accrue once per completed class session';include ROOT_PATH.'/includes/header.php';?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="stats-grid"><div class="stat-card stat-green"><div class="stat-label">Awaiting payout</div><div class="stat-value value-small">Rs.<?=number_format((float)$totals['Earned'],2)?></div></div><div class="stat-card stat-blue"><div class="stat-label">Paid</div><div class="stat-value value-small">Rs.<?=number_format((float)$totals['Paid'],2)?></div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Session</th><th scope="col">Basis</th><th scope="col">Commission</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td><?=e($s['ClassName'])?><br><small><?=e(date('d M Y H:i',strtotime($s['StartsAt'])))?></small></td><td>Rs.<?=number_format((float)$s['RatePerClass'],2)?></td><td><?=$s['Commission']!==null?'Rs.'.number_format((float)$s['Commission'],2):'—'?></td><td><?=e($s['CommissionStatus']??$s['Status'])?></td><td><?php if($s['Status']!=='COMPLETED'&&strtotime($s['StartsAt'])<=time()):?><form method="post"><?=csrf_field()?><input type="hidden" name="session_id" value="<?=$s['SessionID']?>"><button class="btn btn-success btn-sm">Complete session</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php include ROOT_PATH.'/includes/footer.php';?>
